/* Teaching cards — a chunk is two or three rules then a quick check, and it owns the
   questions those rules unlock. The student meets a chunk right before the first
   question that needs it, never as a wall of rules up front.

   Every `formula` is byte-identical to the rule in js/data/<domain>.js: the validator
   compares them, because a card that paraphrases a formula teaches the wrong thing.
   `plain` is that formula in words for the chip — no bare letters, no superscripts,
   Eastern Arabic digits and the signs × ÷ = − + ٪ only. `hook` is the trap or the
   memory line in one breath. One name for one thing: the word `plain` uses is the word
   `say`, `example` and `hook` use.

   Rules a lesson declares but no question needs go in `more`, which is what the
   guidebook («دفتر القوانين») shows. Teaching all of a 28-rule lesson would rebuild
   the wall these cards replaced.

   node tools/validate_teach.js  — caps, coverage, verbatim formulas, no Latin digits.
   node tools/lesson.js <key>    — the lesson exactly as the app sees it. */
